export type IllosFlagState = { enabled: boolean; rollout: number; audiences: string[] };
export type IllosFlagEnvironment = { id: string; label: string } & IllosFlagState;

export type IllosFeatureFlagCardProps = {
  flagKey?: string;
  description?: string;
  environments?: IllosFlagEnvironment[];
  /** The audiences a rollout can target. */
  audiences?: string[];
  defaultEnvironment?: string;
  /** Called with every environment's state on save. Return a promise to keep the saving state until it settles; a rejection keeps the changes unsaved. */
  onSave?: (values: Record<string, IllosFlagState>) => void | Promise<void>;
  /** Colour for the switch, the slider and the illustration's lead. Teal by default; "var(--color-primary)" follows your theme. */
  accent?: string;
  className?: string;
};

const DEFAULT_ENVIRONMENTS: IllosFlagEnvironment[] = [
  { id: "development", label: "Development", enabled: true, rollout: 100, audiences: ["Staff"] },
  { id: "staging", label: "Staging", enabled: true, rollout: 100, audiences: ["Beta users", "Staff"] },
  { id: "production", label: "Production", enabled: true, rollout: 50, audiences: ["Beta users", "Staff"] },
];
const DEFAULT_AUDIENCES = ["Beta users", "Staff", "Free plan", "Paid plans"];

const and = new Intl.ListFormat("en-GB", { type: "conjunction" });
const same = (a: IllosFlagState, b: IllosFlagState) =>
  a.enabled === b.enabled &&
  a.rollout === b.rollout &&
  a.audiences.length === b.audiences.length &&
  a.audiences.every((x) => b.audiences.includes(x));

export function IllosFeatureFlagCard({
  flagKey = "new-checkout",
  description = "One-page checkout with saved cards",
  environments = DEFAULT_ENVIRONMENTS,
  audiences = DEFAULT_AUDIENCES,
  defaultEnvironment,
  onSave,
  accent,
  className,
}: IllosFeatureFlagCardProps) {
  const uid = useId();
  const initial = () =>
    Object.fromEntries(
      environments.map(({ id, enabled, rollout, audiences }) => [id, { enabled, rollout, audiences }]),
    );
  const [saved, setSaved] = useState<Record<string, IllosFlagState>>(initial);
  const [values, setValues] = useState<Record<string, IllosFlagState>>(initial);
  const [envId, setEnvId] = useState(defaultEnvironment ?? environments[environments.length - 1]?.id);
  const [status, setStatus] = useState<"idle" | "saving" | "saved" | "error">("idle");
  const env = environments.find((e) => e.id === envId) ?? environments[0];
  const flag = values[env.id];
  const changed = environments.filter((e) => !same(values[e.id], saved[e.id]));
  const saving = status === "saving";
  const saveRef = useRef<HTMLButtonElement>(null);

  const update = (patch: Partial<IllosFlagState>) => {
    setValues((v) => ({ ...v, [env.id]: { ...v[env.id], ...patch } }));
    setStatus("idle");
  };

  const save = async () => {
    setStatus("saving");
    const next = values;
    try {
      await (onSave ? onSave(next) : new Promise((r) => setTimeout(r, 700)));
      setSaved(next);
      setStatus("saved");
    } catch {
      setStatus("error");
    }
  };

  const who = and.format(audiences.filter((a) => flag.audiences.includes(a)));
  const share = flag.rollout === 100 ? (who ? `all ${who}` : "everyone") : `${flag.rollout}% of ${who || "users"}`;
  const summary = !flag.enabled
    ? `Off in ${env.label}. No one sees it.`
    : flag.rollout === 0
      ? `On in ${env.label}, rolled out to no one yet.`
      : `On for ${share} in ${env.label}.`;
  const track = `linear-gradient(to right, var(--illos-accent) calc(8px + (100% - 16px) * ${flag.rollout / 100}), color-mix(in oklab, var(--color-foreground) 13%, transparent) 0)`;

  return (
    <section
      aria-labelledby={`${uid}-key`}
      className={cx(
        "flex w-full max-w-[540px] flex-col gap-2 rounded-[22px] bg-card p-2 text-card-foreground shadow-[0_0_0_1px_rgb(0_0_0/0.06),0_1px_2px_rgb(0_0_0/0.04),0_16px_40px_-20px_rgb(0_0_0/0.18)] [--illos-accent:#1daf9c] dark:shadow-[0_0_0_1px_rgb(255_255_255/0.09)] dark:[--illos-accent:#3fdec9]",
        className,
      )}
      style={accent ? ({ "--illos-accent": accent } as CSSProperties) : undefined}
    >
      <div className="relative isolate overflow-hidden rounded-[14px] px-[8%] pt-[5%] pb-[3%]" style={WELL}>
        <IllosArt svg={FLAG_SVG} />
      </div>

      <div className="flex flex-col gap-5 px-3 pt-3 pb-2 sm:px-4">
        <div className="flex items-center gap-3">
          <span className="grid size-10 shrink-0 place-items-center rounded-[10px] text-muted-foreground shadow-[0_0_0_1px_rgb(0_0_0/0.07)] dark:bg-muted dark:shadow-[0_0_0_1px_rgb(255_255_255/0.06)]">
            <Icon className="size-[18px]">
              <path d="M5.0249 21C5.04385 19.2643 5.04366 17.5541 5.0366 15.9209M5.0366 15.9209C5.01301 10.4614 4.91276 5.86186 5.19475 4.04271C5.5611 1.67939 9.39301 3.82993 13.9703 5.59842L16.0328 6.48729C17.5508 7.1415 19.7187 8.30352 18.7662 9.66084C18.3738 10.22 17.56 10.8596 16.0575 11.567L5.0366 15.9209Z" />
            </Icon>
          </span>
          <div className="flex min-w-0 flex-col">
            <h2 id={`${uid}-key`} className="truncate text-base font-medium text-foreground">
              {flagKey}
            </h2>
            <p className="truncate text-sm text-muted-foreground">{description}</p>
          </div>
        </div>

        <div role="radiogroup" aria-label="Environment" className="flex gap-1 rounded-[12px] bg-muted p-1">
          {environments.map((e) => (
            <label
              key={e.id}
              className="flex h-9 flex-auto cursor-pointer items-center justify-center gap-1.5 rounded-[8px] px-1.5 text-sm whitespace-nowrap text-muted-foreground sm:gap-2 sm:px-2 transition-[background-color,color,box-shadow] duration-150 ease-out hover:text-foreground has-checked:bg-card has-checked:text-foreground has-checked:shadow-[0_0_0_1px_rgb(0_0_0/0.06),0_1px_2px_rgb(0_0_0/0.08)] has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-ring dark:has-checked:bg-[color-mix(in_oklab,var(--color-foreground)_10%,var(--color-card))] dark:has-checked:shadow-none"
            >
              <input
                type="radio"
                name={`${uid}-env`}
                className="sr-only"
                checked={e.id === env.id}
                onChange={() => setEnvId(e.id)}
              />
              <span
                aria-hidden="true"
                className={cx(
                  "size-1.5 shrink-0 rounded-full",
                  values[e.id].enabled ? "bg-[var(--illos-accent)]" : "bg-foreground/25",
                )}
              />
              {e.label}
            </label>
          ))}
        </div>

        <div className="flex flex-col gap-5">
          <label htmlFor={`${uid}-on`} className="flex cursor-pointer items-center justify-between gap-4">
            <span className="text-sm text-muted-foreground">Status</span>
            <span className="flex items-center gap-2.5">
              <span className="text-sm font-medium text-foreground" aria-hidden="true">
                {flag.enabled ? "On" : "Off"}
              </span>
              <button
                id={`${uid}-on`}
                type="button"
                role="switch"
                aria-checked={flag.enabled}
                aria-label={`Enabled in ${env.label}`}
                onClick={() => update({ enabled: !flag.enabled })}
                className="group inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full bg-foreground/15 transition-colors duration-150 ease-out outline-offset-2 focus-visible:outline-2 focus-visible:outline-ring aria-checked:bg-[var(--illos-accent)] motion-reduce:transition-none"
              >
                <span className="size-4 translate-x-0.5 rounded-full bg-white shadow-[0_1px_2px_rgb(0_0_0/0.25)] transition-transform duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] group-aria-checked:translate-x-[18px] motion-reduce:transition-none" />
              </button>
            </span>
          </label>

          <div className="flex flex-col gap-2.5">
            <div className="flex items-center justify-between gap-4">
              <label htmlFor={`${uid}-rollout`} className="text-sm text-muted-foreground">
                Rollout
              </label>
              <span className="text-sm font-medium tabular-nums text-foreground">{flag.rollout}%</span>
            </div>
            <div className="flex flex-col gap-2">
              <input
                id={`${uid}-rollout`}
                type="range"
                min={0}
                max={100}
                step={5}
                value={flag.rollout}
                aria-valuetext={`${flag.rollout}%`}
                aria-describedby={`${uid}-summary`}
                onChange={(e) => update({ rollout: Number(e.target.value) })}
                style={{ "--track": track } as CSSProperties}
                className="h-8 w-full cursor-pointer appearance-none rounded-full bg-transparent outline-offset-2 focus-visible:outline-2 focus-visible:outline-ring [&::-moz-range-thumb]:size-4 [&::-moz-range-thumb]:rounded-full [&::-moz-range-thumb]:border-0 [&::-moz-range-thumb]:bg-white [&::-moz-range-thumb]:shadow-[0_0_0_1px_rgb(0_0_0/0.14),0_1px_3px_rgb(0_0_0/0.2)] [&::-moz-range-track]:h-1.5 [&::-moz-range-track]:rounded-full [&::-moz-range-track]:bg-(image:--track) [&::-webkit-slider-runnable-track]:h-1.5 [&::-webkit-slider-runnable-track]:rounded-full [&::-webkit-slider-runnable-track]:bg-(image:--track) [&::-webkit-slider-thumb]:-mt-[5px] [&::-webkit-slider-thumb]:size-4 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:shadow-[0_0_0_1px_rgb(0_0_0/0.14),0_1px_3px_rgb(0_0_0/0.2)]"
              />
              <p id={`${uid}-summary`} className="text-sm text-muted-foreground">
                {summary}
              </p>
            </div>
          </div>

          <div className="flex flex-col gap-2.5">
            <span id={`${uid}-aud`} className="text-sm text-muted-foreground">
              Audience
            </span>
            <div role="group" aria-labelledby={`${uid}-aud`} className="flex flex-wrap gap-2">
              {audiences.map((a) => {
                const on = flag.audiences.includes(a);
                return (
                  <button
                    key={a}
                    type="button"
                    aria-pressed={on}
                    onClick={() =>
                      update({ audiences: on ? flag.audiences.filter((x) => x !== a) : [...flag.audiences, a] })
                    }
                    className={cx(
                      "relative inline-flex h-9 cursor-pointer items-center gap-1.5 rounded-full pr-3.5 pl-2.5 text-sm transition-[background-color,color,box-shadow,scale] duration-150 ease-out outline-offset-2 before:absolute before:inset-x-0 before:-inset-y-1 focus-visible:outline-2 focus-visible:outline-ring active:scale-[0.96]",
                      on
                        ? "bg-[color-mix(in_oklab,var(--illos-accent)_14%,var(--color-card))] text-foreground shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--illos-accent)_55%,transparent)]"
                        : "text-muted-foreground shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-foreground)_13%,transparent)] hover:bg-muted hover:text-foreground",
                    )}
                  >
                    <Icon className={cx("size-3.5", on && "text-[var(--illos-accent)]")}>
                      <path d={on ? "M5 14L8.5 17.5L19 6.5" : "M12 4V20M20 12H4"} />
                    </Icon>
                    {a}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1.5 rounded-[14px] bg-muted/70 p-1.5 pl-4 sm:flex-nowrap">
        <p
          role="status"
          className="flex min-h-9 w-full min-w-0 items-center gap-2 text-sm text-muted-foreground sm:w-auto sm:flex-1"
        >
          {status === "error" ? (
            <>
              <span className="size-1.5 shrink-0 rounded-full bg-foreground" aria-hidden="true" />
              <span className="text-foreground">Couldn’t save. Try again.</span>
            </>
          ) : saving ? (
            "Saving…"
          ) : changed.length ? (
            <>
              <span className="size-1.5 shrink-0 rounded-full bg-[var(--illos-accent)]" aria-hidden="true" />
              <span className="truncate">Unsaved changes in {and.format(changed.map((e) => e.label))}</span>
            </>
          ) : (
            <>
              <Icon className="size-4 shrink-0 text-[var(--illos-accent)]">
                <path d="M5 14L8.5 17.5L19 6.5" />
              </Icon>
              {status === "saved" ? "Changes saved" : "Up to date"}
            </>
          )}
        </p>
        <div className="ml-auto flex items-center gap-1.5">
          <button
            type="button"
            onClick={() => {
              setValues(saved);
              setStatus("idle");
              saveRef.current?.focus(); // Discard hides itself, so keep focus in the footer
            }}
            className={cx(
              "inline-flex h-9 cursor-pointer items-center rounded-lg px-3 text-sm font-medium text-foreground transition-[background-color,scale] duration-150 ease-out outline-offset-2 hover:bg-foreground/5 focus-visible:outline-2 focus-visible:outline-ring active:scale-[0.97]",
              (!changed.length || saving) && "invisible",
            )}
          >
            Discard
          </button>
          {/* aria-disabled, not disabled, so the button keeps focus once the changes are saved */}
          <button
            ref={saveRef}
            type="button"
            onClick={() => changed.length > 0 && !saving && save()}
            aria-disabled={!changed.length || saving}
            className="inline-flex h-9 min-w-[5.5rem] cursor-pointer items-center justify-center rounded-lg bg-primary px-3.5 text-sm font-medium text-primary-foreground transition-[background-color,opacity,scale] duration-150 ease-out outline-offset-2 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-ring active:scale-[0.97] aria-disabled:cursor-default aria-disabled:opacity-50 aria-disabled:hover:bg-primary aria-disabled:active:scale-100"
          >
            {saving ? "Saving…" : "Save"}
          </button>
        </div>
      </div>
    </section>
  );
}

